<?php use App\Core\Csrf; use App\Helpers\ViewHelper; ?>
<div class="page-head"><p class="eyebrow">Khuyến mại</p><h1>Mã giảm giá</h1></div>
<?php if (!empty($error)): ?><div class="notice"><?= ViewHelper::escape($error) ?></div><?php endif; ?>
<form class="form-card" method="post" action="/admin/vouchers"><?= Csrf::field() ?><div class="form-grid"><label>Mã voucher<input name="code" placeholder="WELCOME10" required></label><label>Loại<select name="type"><option value="percent">Theo phần trăm</option><option value="fixed">Theo số tiền</option></select></label><label>Giá trị<input name="value" type="number" min="1" required></label><label>Đơn tối thiểu<input name="min_order_amount" type="number" min="0" value="0"></label><label>Bắt đầu<input name="starts_at" type="datetime-local"></label><label>Kết thúc<input name="expires_at" type="datetime-local"></label><label>Giới hạn lượt dùng<input name="usage_limit" type="number" min="1" placeholder="Không giới hạn"></label></div><button class="button button-primary" type="submit">Tạo voucher</button></form>
<div class="table-wrap"><table class="admin-table voucher-table"><thead><tr><th>Mã</th><th>Loại</th><th>Giá trị</th><th>Hiệu lực</th><th>Đã dùng</th><th>Thao tác</th></tr></thead><tbody><?php foreach ($vouchers as $voucher): ?><tr><td><strong><?= ViewHelper::escape($voucher['code']) ?></strong></td><td><?= $voucher['type'] === 'percent' ? 'Phần trăm' : 'Số tiền' ?></td><td><?= (int)$voucher['value'] ?><?= $voucher['type'] === 'percent' ? '%' : ' đ' ?></td><td><?= ViewHelper::escape((string)($voucher['expires_at'] ?: 'Không thời hạn')) ?></td><td><?= (int)$voucher['used_count'] ?><?= $voucher['usage_limit'] === null ? '' : ' / ' . (int)$voucher['usage_limit'] ?></td><td><form method="post" action="/admin/vouchers/<?= (int)$voucher['id'] ?>/delete"><?= Csrf::field() ?><button class="action-button action-button-danger button-small" type="submit">Xóa</button></form></td></tr><?php endforeach; ?></tbody></table></div>
